def icom(r,inputs,outputs,controls,mechanisms):
 for name,items in [('Входы (I)',inputs),('Управление (C)',controls),('Выходы (O)',outputs),('Механизмы (M)',mechanisms)]:
  r.p(name+': '+', '.join(items)+'.')

def build():
 r=Report(5,'Методология функционального моделирования IDEF0','','')
 r.heading('ЦЕЛЬ ПРАКТИЧЕСКОЙ РАБОТЫ')
 r.p('Цель работы: построить функциональные модели предоставления двух ИТ-услуг ООО «ТехноСервис» в нотации IDEF0. Для каждой услуги разработать контекстную диаграмму, декомпозицию первого уровня на четыре функции и второй уровень для каждой функции, определить входы, выходы, управление и механизмы.')
 r.heading('ВЫПОЛНЕНИЕ РАБОТЫ')
 r.sub('1. Выбор услуг и правила моделирования')
 r.p('Выбраны услуги разных линий: аренда виртуальных серверов из линии «Доступ/аренда» и мониторинг с поддержкой из линии «Управление». Механизмы соответствуют сервисно-ресурсным моделям предприятия; управляющие правила согласованы с SLA практической работы №4.')
 r.p('В IDEF0 входы подходят слева, выходы отходят справа, управление поступает сверху, механизмы - снизу. Блоки названы глаголами. Контекст A-0 содержит функцию A0; диаграмма A0 раскрывает её на A1, A2, A3 и A4. Каждый из четырёх блоков раскрыт на три функции второго уровня.')
 r.p('Листы выполнены в стиле образца: светлый фон, тонкие чёрные контуры, ортогональные связи, отдельные подписи ICOM, номер блока в правом нижнем углу, рамка и штамп с узлом, названием и номером листа. Для каждой услуги используется собственное дерево нумерации.')
 r.p('Границы моделей охватывают полный путь от получения исходных данных до предоставления согласованного результата. Внешние ИТ-продукты выступают механизмами; функции описывают деятельность по оказанию услуг.')
 r.table('Состав комплекта моделей',['Услуга','Контекст','Первый уровень','Второй уровень'],[
 ['Аренда виртуальных серверов','A-0: блок A0','A0: A1, A2, A3, A4','A1, A2, A3, A4; по 3 функции'],
 ['Мониторинг и поддержка','A-0: блок A0','A0: A1, A2, A3, A4','A1, A2, A3, A4; по 3 функции']],[5,3.3,3.9,4.3])
 for modelno,m in enumerate(MODELS,2):
  r.sub(f'{modelno}. '+m['service'],True)
  r.minor(f'{modelno}.1 Контекстная диаграмма A-0')
  r.figure(ROOT/'diagrams/png'/(m['key']+'_Aminus0.png'),m['service']+'. Контекстная диаграмма A-0')
  icom(r,m['inputs'],m['outputs'],m['controls'],m['mechanisms'])
  r.minor(f'{modelno}.2 Декомпозиция первого уровня A0',True)
  r.figure(ROOT/'diagrams/png'/(m['key']+'_A0.png'),m['service']+'. Декомпозиция A0')
  for i,s in enumerate(m['stages'],1):r.p(f'A{i}. {s["name"]}. Результат: '+', '.join(s['outputs'])+'.')
  r.p('Выход предыдущей функции становится входом следующей. Дополнительные внешние сведения подаются на соответствующий этап. Граничные входы и выходы совпадают с контекстом; управления и механизмы разветвляются только к использующим их функциям.')
  for i,s in enumerate(m['stages'],1):
   r.minor(f'{modelno}.{i+2} Второй уровень A{i}',True)
   r.figure(ROOT/'diagrams/png'/(m['key']+f'_A{i}.png'),f'{m["service"]}. {s["name"]}, узел A{i}')
   icom(r,s['inputs'],s['outputs'],[m['controls'][j] for j in s['controls']],[m['mechanisms'][j] for j in s['mechanisms']])
   r.p(EXPLANATIONS[m['key']][i-1])
 r.sub('4. Проверка полноты и согласованности',True)
 r.p('Получено 12 диаграмм: два контекста, две декомпозиции первого уровня и восемь декомпозиций второго уровня. Каждое дерево содержит один контекстный блок, четыре блока первого уровня и двенадцать блоков второго уровня. Нераскрытых функций первого уровня нет.')
 rows=[]
 for m in MODELS:
  for i,s in enumerate(m['stages'],1):rows.append([('Аренда ВМ' if m['key']=='vps' else 'Мониторинг')+f', A{i}',', '.join(s['inputs']),', '.join(s['outputs'])])
 r.table('Балансировка родительских и дочерних диаграмм',['Модель и узел','Вход дочерней диаграммы','Выход дочерней диаграммы'],rows,[3.5,6.5,6.5])
 r.p('На втором уровне сохранены входы и выходы родительского блока; его управляющие воздействия и механизмы распределены между дочерними функциями. Внутренние результаты служат связями между этапами и не создают новых внешних результатов. Нумерация и подписи согласованы между рисунками и описаниями.')
 r.p('Редактируемые файлы .drawio, векторные SVG и PNG высокого разрешения сохранены в diagrams. Для модели аренды используется префикс vps, для мониторинга - monitoring. Сведения об узлах и ICOM находятся в idef0-index.json. Учёт инцидентов и сроков реализуется в работе №6; развёртывание ВМ и сбор метрик остаются операциями профильных систем.')
 r.heading('Вывод по работе')
 r.p('Построены модели аренды виртуальных серверов и мониторинга с поддержкой ООО «ТехноСервис». Для каждой услуги выполнены контекст, декомпозиция на четыре функции и второй уровень всех четырёх функций. Всего разработано 12 диаграмм в оформлении предоставленного образца.')
 r.p('Определены ICOM и промежуточные результаты, проверены балансировка и полнота деревьев. Модели сохраняют каталог, технические ресурсы и условия SLA единого проекта и показывают контрольные точки предоставления и восстановления услуг.')
 return r.save()
if __name__=='__main__':print(build())
